sys_script_include.script:
var AutoNumberGenerator = Class.create();
AutoNumberGenerator.prototype = {
    initialize: function() {},

    /**
     * Generates the next sequential ID for a given table/field.
     * Formula: PREFIX-YYYY-NNN where NNN = total records + 1 (with collision fallback).
     *
     * @param {string} tableName  - Full scoped table name
     * @param {string} fieldName  - Field to populate
     * @param {string} prefix     - ID prefix (e.g. 'ORD', 'ITEM')
     * @param {number} padding    - Zero-pad width for the sequence number
     * @param {boolean} includeYear - true to include YYYY in the pattern
     * @returns {string} The generated identifier
     */
    generate: function(tableName, fieldName, prefix, padding, includeYear) {
        var year = '';
        var searchPrefix = '';

        if (includeYear) {
            var gdt = new GlideDateTime();
            year = '' + gdt.getYearUTC();
            searchPrefix = prefix + '-' + year + '-';
        } else {
            searchPrefix = prefix + '-';
        }

        // Count total records in the table
        var ga = new GlideAggregate(tableName);
        ga.addAggregate('COUNT');
        ga.query();
        var totalCount = 0;
        if (ga.next()) {
            totalCount = parseInt(ga.getAggregate('COUNT'), 10);
        }

        // Find the max existing sequence number for collision avoidance
        var gr = new GlideRecord(tableName);
        gr.addQuery(fieldName, 'STARTSWITH', searchPrefix);
        gr.query();

        var maxSeq = 0;
        while (gr.next()) {
            var value = '' + gr.getValue(fieldName);
            var parts = value.split('-');
            var lastPart = parts[parts.length - 1];
            var num = parseInt(lastPart, 10);
            if (!isNaN(num) && num > maxSeq) {
                maxSeq = num;
            }
        }

        // Start from count+1; if that collides (≤ maxSeq), fall back to maxSeq+1
        var nextSeq = totalCount + 1;
        if (nextSeq <= maxSeq) {
            nextSeq = maxSeq + 1;
        }

        // Build candidate
        var paddedSeq = '' + nextSeq;
        while (paddedSeq.length < padding) {
            paddedSeq = '0' + paddedSeq;
        }

        var candidate;
        if (includeYear) {
            candidate = prefix + '-' + year + '-' + paddedSeq;
        } else {
            candidate = prefix + '-' + paddedSeq;
        }

        // Collision check — keep incrementing until a free number is found
        var checkGr = new GlideRecord(tableName);
        checkGr.addQuery(fieldName, candidate);
        checkGr.setLimit(1);
        checkGr.query();
        while (checkGr.hasNext()) {
            nextSeq++;
            paddedSeq = '' + nextSeq;
            while (paddedSeq.length < padding) {
                paddedSeq = '0' + paddedSeq;
            }
            if (includeYear) {
                candidate = prefix + '-' + year + '-' + paddedSeq;
            } else {
                candidate = prefix + '-' + paddedSeq;
            }
            checkGr = new GlideRecord(tableName);
            checkGr.addQuery(fieldName, candidate);
            checkGr.setLimit(1);
            checkGr.query();
        }

        return candidate;
    },

    type: 'AutoNumberGenerator'
};
